    def fail(self, k: str, msg: str):
        self.K[k] = False
        self.errors.append(f"{k}: {msg}")

    def ok(self, k: str):
        self.K[k] = True

    # -------------------------------------------------------------------
    # Step runner
    # -------------------------------------------------------------------

    def run(self) -> bool:
        logging.debug("=== PHASE 0.5 VALIDATION (K1–K40 + SEMANTIC) ===")

        self._run_step(0, self._validate_ssot)
        self._run_step(1, self._validate_structure)
        self._run_step(2, self._validate_global_artifacts)
        self._run_step(3, self._validate_archive_local)
        self._run_step(4, self._validate_semantic_artifacts)
        self._run_step(5, self._validate_canonical_pointers)
        self._run_step(6, self._validate_safety)
        self._run_step(7, self._validate_quality)
        self._run_step(8, self._validate_completion)

        self._report()
        return self.K["K40"]

    def _run_step(self, index: int, fn):
        step = self.steps[index]
        step.status = "RUNNING"
        step.start = datetime.now().isoformat()
        try:
            ok = fn(step)
            step.status = "COMPLETED" if ok else "FAILED"
        except Exception as e:
            step.status = "FAILED"
            step.error = str(e)
            self.errors.append(f"[{step.step_id}] {e}")
        step.end = datetime.now().isoformat()

    # ==================================================================
    # STEP 1 — SSoT CHECKS (K1–K9)
    # ==================================================================

    def _validate_ssot(self, step: ValidationStep) -> bool:
        ssot = PROJECT_ROOT / "unified_structure_subatomic.yaml"
        meta = PROJECT_ROOT / "unified_structure_subatomic_meta.yaml"

        if ssot.exists(): self.ok("K1")
