    def _validate_archive_local(self, step: ValidationStep) -> bool:
        ok = True

        for dom in ARCHIVE_LOCAL_DOMAINS:
            for ptr in (CACHE_ROOT / dom).rglob("*.json"):
                data = read_json(ptr)
                h = data.get("hash")
                if h not in self.global_hashes:
                    self.fail("K19", f"Archive-local pointer references invalid hash {h}")
                    ok = False

        if ok:
            self.ok("K18"); self.ok("K19"); self.ok("K20")

        return ok

    # ==================================================================
    # STEP 5 — SEMANTIC COMPONENT CHECK (NEW)
    # ==================================================================

    def _validate_semantic_artifacts(self, step: ValidationStep) -> bool:
        ok = True
        semantic_root = CACHE_ROOT / "semantic"

        if not semantic_root.exists():
            self.fail("K23", "Missing semantic/ directory")
            return False

        # 1. Check consistency: Global Hash -> Semantic File
        for h in self.global_hashes:
            sf = semantic_root / f"{h}.semantic.json"
            if not sf.exists():
                self.fail("K23", f"Missing semantic artifact for {h}")
                ok = False
                continue

            data = read_json(sf)
            comps = data.get("components")
            if not isinstance(comps, list) or not comps:
                self.fail("K23", f"Semantic file {sf} has no components")
                ok = False
                continue

            cid_set = set()
            for c in comps:
                cid = c.get("component_id")
                if not cid:
                    self.fail("K23", f"Component missing id in {sf}")
                    ok = False
                    continue
                if cid in cid_set:
                    self.fail("K23", f"Duplicate component_id in {sf}: {cid}")
                    ok = False
                cid_set.add(cid)

            self.components_by_hash[h] = cid_set
            self.semantic_hashes.add(h)

        # Must have semantic artifacts for EVERY hash
        missing = self.global_hashes - self.semantic_hashes
        if missing:
            self.fail("K23", f"Missing semantic artifacts for hashes: {sorted(missing)}")
            ok = False

        # 2. Check for Orphaned Semantic Files (Garbage Collection Check)
        all_semantic_files = {f.name.replace(".semantic.json", "") for f in semantic_root.glob("*.semantic.json")}
        orphans = all_semantic_files - self.global_hashes
        if orphans:
            self.fail("K23", f"Found {len(orphans)} orphaned semantic artifacts (not in global hashes): {list(orphans)[:3]}...")
            ok = False

        # 3. Deep Validate Component Graph (K24)
        graph_path = CACHE_ROOT / "graphs" / "component_graph.json"
        if not graph_path.exists():
            self.fail("K24", "Missing component_graph.json")
            ok = False
        else:
            graph = read_json(graph_path)
            nodes = graph.get("nodes", [])
            edges = graph.get("edges", [])

            if not isinstance(nodes, list) or not nodes:
                self.fail("K24", "Graph has no nodes")
                ok = False
            elif not isinstance(edges, list):
                self.fail("K24", "Graph edges malformed")
                ok = False
            else:
                # Strict Connectivity Check: Do all edges point to valid nodes?
                valid_node_ids = {n.get("component_id") for n in nodes if n.get("component_id")}
                dangling_edges = []
                
                for i, edge in enumerate(edges):
                    src = edge.get("from")
                    dst = edge.get("to")
                    if src not in valid_node_ids:
                        dangling_edges.append(f"Edge[{i}] source '{src}' missing")
                    if dst not in valid_node_ids:
                        dangling_edges.append(f"Edge[{i}] target '{dst}' missing")
                
                if dangling_edges:
                    self.fail("K24", f"Graph contains {len(dangling_edges)} dangling edges: {dangling_edges[:3]}...")
                    ok = False

        return ok

    # ==================================================================
    # STEP 6 — CANONICAL COMPONENT POINTER CHECK (SEMANTIC K11)
    # ==================================================================

    def _validate_canonical_pointers(self, step: ValidationStep) -> bool:
        ok = True

        for bucket in SEMANTIC_BUCKETS:
            bucket_root = CACHE_ROOT / bucket
            if not bucket_root.exists():
                self.fail("K11", f"Missing canonical bucket {bucket}")
                ok = False
                continue

            for ptr in bucket_root.rglob("*.json"):
                data = read_json(ptr)
                h = data.get("hash")
                cid = data.get("component_id")

                if h not in self.global_hashes:
                    self.fail("K11", f"Pointer {ptr} references unknown hash {h}")
                    ok = False
                    continue

                if h not in self.components_by_hash:
                    self.fail("K11", f"Pointer {ptr} → hash {h} missing semantic components")
                    ok = False
                    continue

                if cid not in self.components_by_hash[h]:
                    self.fail("K11", f"Pointer {ptr} → invalid component_id {cid}")
                    ok = False

        if ok: self.ok("K11")
        return ok

